    analysis_neutral_intro: 'Colorant déposé le long de l’axe neutre (a*=b*=0) à mesure que la clarté passe du blanc (L*=100) au noir (L*=0).',
    analysis_neutral_err_output: 'L’encrage de l’axe neutre n’est disponible que pour les profils de sortie (imprimante).',
