    analysis_neutral_tone: 'L* en sortie (tonalité)',
    analysis_neutral_de: 'Δa*b*',
    analysis_extrema_heading: 'Colorimétrie des extrêmes',
    analysis_extrema_intro: 'Les extrémités de la plage de reproduction du profil : le blanc du support, le noir le plus dense qu’il imprimera, l’encre que ce noir coûte, et l’endroit où chaque teinte atteint son point le plus saturé.',
    analysis_extrema_method: 'Le point blanc est la couleur à colorant nul — le support nu. Le point noir est obtenu en faisant passer le noir PCS (L*=0, a*=b*=0) par la table B2A sélectionnée pour obtenir l’encrage que le profil choisit pour le noir, puis en relisant cet encrage via A2B1. La couverture d’encre totale (TAC) est la somme de cet encrage. La colorimétrie absolue montre la couleur propre du support ; la relative la ramène à un blanc parfait.',
    analysis_extrema_rel: 'Relative',
    analysis_extrema_abs: 'Absolue',
    analysis_extrema_white: 'Point blanc',
    analysis_extrema_black: 'Point noir',
    analysis_extrema_blackink: 'Encrage au point noir',
    analysis_extrema_tac: 'TAC',
    analysis_extrema_noabs: 'Ce profil n’a pas de balise de point blanc du média ; la colorimétrie absolue est donc indisponible.',
    analysis_extrema_err_output: 'La colorimétrie des extrêmes n’est disponible que pour les profils de sortie (imprimante) — elle suppose qu’un colorant nul correspond au support nu.',
    analysis_extrema_hue_heading: 'Aplat et chroma maximal',
    analysis_extrema_hue_intro: 'Où se situe chaque coin d’encre, et le point le plus chromatique sur le chemin. Mesuré via A2B1 : ces lignes ne changent donc pas avec l’intention de rendu ci-dessus. Sur un profil sain, les deux lignes coïncident ; si le chroma maximal survient avant l’aplat, l’encre ajoutée au-delà ne fait qu’assombrir.',
    analysis_extrema_hue: 'Teinte',
    analysis_extrema_fulltone: 'Aplat',
    analysis_extrema_maxc: 'C* max',
    analysis_extrema_at: 'À l’encrage',
    analysis_extrema_early: 'Le chroma maximal est atteint avant l’aplat — au-delà, l’encre ne fait qu’assombrir.',
    analysis_shadow_heading: 'Utilisation d’encre dans les ombres',
    analysis_shadow_intro: 'Quatre trajets rectilignes dans le plan a*b* à une clarté constante et délibérément sombre, passés par la table B2A sélectionnée. Tous les échantillons partagent la même L*, de sorte que tout saut brusque ou inversion d’un colorant provient uniquement du traitement de la teinte et du chroma — la signature d’un artefact de mappage de gamut dans les ombres.',
    analysis_shadow_err_output: 'L’utilisation d’encre dans les ombres n’est disponible que pour les profils de sortie (imprimante).',
    analysis_shadow_plane: 'Plan à L* constante',
    analysis_shadow_bpc: 'avec compensation du point noir depuis',
    analysis_shadow_xaxis: 'Position le long du trajet',
    analysis_primary_heading: 'Chemins d’encrage primaire par le neutre',
    analysis_primary_intro: 'Trois chemins dans le gamut — cyan→rouge, magenta→vert, jaune→bleu — chacun passant par l’axe neutre à la clarté médiane de ses extrémités, à travers la table B2A sélectionnée. Chaque échantillon est dans le gamut, donc contrairement aux chemins d’ombre, toute rupture ou inversion d’un colorant traduit un défaut de régularité de la CLUT plutôt qu’un artefact de mappage de gamut.',
    analysis_primary_err_output: 'Les chemins d’encrage primaire ne sont disponibles que pour les profils de sortie (imprimante).',
    analysis_primary_xaxis: 'Position le long du chemin (neutre au milieu)',
    analysis_primary_bpc: 'Compensation du point noir appliquée pour cette intention.',
    analysis_inkusage_heading: 'Statistiques d’utilisation d’encre',
    analysis_inkusage_intro: 'La quantité de chaque colorant déposée par le profil, en somme et en part du total — la signature de consommation d’encre de la séparation.',
    analysis_inkusage_err_output: 'Les statistiques d’utilisation d’encre ne sont disponibles que pour les profils de sortie (imprimante).',
    analysis_inkusage_neutral: 'Axe neutre',
    analysis_inkusage_mean: 'Couverture moyenne',
    analysis_inkusage_share: 'Part d’encre',
