    analysis_rt_heading: 'Rundlauf (PRMG)',
    analysis_rt_intro: 'Rundlauf über den Gerätewürfel des Profils, entsprechend dem Referenzwerkzeug iccRoundTrip. Rundlauf 1 ist der Fehler Gerät→PCS→Gerät (ΔE*ab); Rundlauf 2 misst die Stabilität des PCS-Rundlaufs. Das PRMG-Histogramm zeigt die Interoperabilität gegenüber dem Perceptual Reference Medium Gamut.',
