    tab_header: 'Header', tab_tags: 'Tags', tab_validation: 'Validierung', tab_analysis: 'Analyse',
    analysis_neutral_heading: 'Neutralachsen-Einfärbung',
    analysis_neutral_intro: 'Auf der Neutralachse (a*=b*=0) aufgetragene Farbe, während die Helligkeit von Weiß (L*=100) zu Schwarz (L*=0) verläuft.',
    analysis_neutral_err_output: 'Die Neutralachsen-Einfärbung ist nur für Ausgabeprofile (Drucker) verfügbar.',
    analysis_neutral_na: 'Dieses Profil hat keine B2A-Tabelle (PCS→Gerät) zum Abtasten.',
    analysis_intent_label: 'Render-Intent', analysis_neutral_yaxis: '% Farbe',
    analysis_neutral_tone: 'L* Ausgabe (Tonwert)',
    analysis_neutral_de: 'Δa*b*',
    analysis_extrema_heading: 'Kolorimetrie der Extremwerte',
    analysis_extrema_intro: 'Die Enden des Wiedergabeumfangs des Profils: das Weiß des Bedruckstoffs, das dunkelste Schwarz, das es druckt, der Farbauftrag, den dieses Schwarz kostet, und der Punkt, an dem jeder Farbton am gesättigtsten ist.',
    analysis_extrema_method: 'Der Weißpunkt ist die Farbe bei null Farbmittel — der blanke Bedruckstoff. Der Schwarzpunkt ergibt sich, indem PCS-Schwarz (L*=0, a*=b*=0) durch die gewählte B2A-Tabelle geführt wird, um den Farbauftrag zu erhalten, den das Profil für Schwarz wählt, und dieser Farbauftrag anschließend über A2B1 zurückgelesen wird. Der Gesamtfarbauftrag (TAC) ist die Summe dieses Farbauftrags. Die absolute Kolorimetrie zeigt die Eigenfarbe des Bedruckstoffs; die relative bezieht sie auf ein perfektes Weiß.',
    analysis_extrema_rel: 'Relativ',
    analysis_extrema_abs: 'Absolut',
    analysis_extrema_white: 'Weißpunkt',
    analysis_extrema_black: 'Schwarzpunkt',
    analysis_extrema_blackink: 'Farbauftrag am Schwarzpunkt',
    analysis_extrema_tac: 'TAC',
    analysis_extrema_noabs: 'Dieses Profil hat kein Medien-Weißpunkt-Tag, daher ist die absolute Kolorimetrie nicht verfügbar.',
    analysis_extrema_err_output: 'Die Kolorimetrie der Extremwerte ist nur für Ausgabeprofile (Drucker) verfügbar — sie setzt voraus, dass null Farbmittel dem blanken Bedruckstoff entspricht.',
    analysis_extrema_hue_heading: 'Vollton gegenüber maximalem Chroma',
    analysis_extrema_hue_intro: 'Wo jede Farbecke landet und der farbigste Punkt auf dem Weg dorthin. Gemessen über A2B1, daher ändern sich diese Zeilen nicht mit dem Render-Intent oben. Bei einem gutmütigen Profil stimmen beide Zeilen überein; wird das maximale Chroma vor dem Vollton erreicht, verdunkelt die Farbe darüber hinaus nur noch.',
    analysis_extrema_hue: 'Farbton',
    analysis_extrema_fulltone: 'Vollton',
    analysis_extrema_maxc: 'Max. C*',
    analysis_extrema_at: 'Bei Farbauftrag',
    analysis_extrema_early: 'Das maximale Chroma wird vor dem Vollton erreicht — Farbe darüber hinaus verdunkelt nur.',
    analysis_shadow_heading: 'Farbverbrauch in den Tiefen',
    analysis_shadow_intro: 'Vier gerade Pfade durch die a*b*-Ebene bei einer konstanten, bewusst dunklen Helligkeit, geführt durch die gewählte B2A-Tabelle. Alle Abtastwerte teilen dieselbe L*, sodass jeder abrupte Sprung oder jede Umkehr eines Farbmittels allein aus der Behandlung von Farbton und Chroma stammt — die Signatur eines Gamut-Mapping-Artefakts in den Tiefen.',
    analysis_shadow_err_output: 'Der Farbverbrauch in den Tiefen ist nur für Ausgabeprofile (Drucker) verfügbar.',
    analysis_shadow_plane: 'Ebene konstanter L*',
    analysis_shadow_bpc: 'schwarzpunktkompensiert ab',
    analysis_shadow_xaxis: 'Position entlang des Pfades',
    analysis_primary_heading: 'Primärfarben-Pfade durch Neutral',
    analysis_primary_intro: 'Drei Pfade im Gamut — Cyan→Rot, Magenta→Grün, Gelb→Blau — jeder durch die Neutralachse bei der mittleren Helligkeit seiner Endpunkte, durch die gewählte B2A-Tabelle geführt. Jeder Messpunkt liegt im Gamut, daher ist – anders als bei den Schattenpfaden – jede abrupte Stufe oder Umkehr eines Farbmittels ein CLUT-Glättungsfehler und kein Gamut-Mapping-Artefakt.',
    analysis_primary_err_output: 'Primärfarben-Pfade sind nur für Ausgabeprofile (Drucker) verfügbar.',
    analysis_primary_xaxis: 'Position entlang des Pfades (Neutral in der Mitte)',
    analysis_primary_bpc: 'Schwarzpunktkompensation für diese Absicht angewendet.',
    analysis_inkusage_heading: 'Farbverbrauchsstatistik',
    analysis_inkusage_intro: 'Wie viel von jedem Farbmittel das Profil aufträgt, als Summe und als Anteil am Gesamtwert — die Farbverbrauchssignatur der Separation.',
    analysis_inkusage_err_output: 'Die Farbverbrauchsstatistik ist nur für Ausgabeprofile (Drucker) verfügbar.',
