    analysis_rt_heading: 'Andata e ritorno (PRMG)',
    analysis_rt_intro: 'Andata e ritorno sul cubo dispositivo del profilo, come lo strumento di riferimento iccRoundTrip. L’andata e ritorno 1 è l’errore dispositivo→PCS→dispositivo (ΔE*ab); l’andata e ritorno 2 misura la stabilità del ciclo PCS. L’istogramma PRMG indica l’interoperabilità rispetto al Perceptual Reference Medium Gamut.',
