    analysis_neutral_heading: 'Inchiostrazione dell’asse neutro',
    analysis_neutral_intro: 'Colorante depositato lungo l’asse neutro (a*=b*=0) mentre la luminosità passa dal bianco (L*=100) al nero (L*=0).',
    analysis_neutral_err_output: 'L’inchiostrazione dell’asse neutro è disponibile solo per i profili di output (stampante).',
    analysis_neutral_na: 'Questo profilo non ha una tabella B2A (PCS→dispositivo) da campionare.',
    analysis_intent_label: 'Intento di rendering', analysis_neutral_yaxis: '% inchiostro',
    analysis_neutral_tone: 'L* in uscita (tono)',
    analysis_neutral_de: 'Δa*b*',
    analysis_extrema_heading: 'Colorimetria degli estremi',
    analysis_extrema_intro: 'Gli estremi dell’intervallo di riproduzione del profilo: il bianco del supporto, il nero più scuro che stamperà, l’inchiostro che quel nero costa e il punto in cui ogni tinta raggiunge la massima saturazione.',
    analysis_extrema_method: 'Il punto di bianco è il colore con colorante nullo — il supporto nudo. Il punto di nero si ottiene facendo passare il nero PCS (L*=0, a*=b*=0) attraverso la tabella B2A selezionata per ricavare l’inchiostrazione che il profilo sceglie per il nero, e rileggendo poi tale inchiostrazione tramite A2B1. La copertura totale d’inchiostro (TAC) è la somma di tale inchiostrazione. La colorimetria assoluta mostra il colore proprio del supporto; quella relativa lo riferisce a un bianco perfetto.',
    analysis_extrema_rel: 'Relativa',
    analysis_extrema_abs: 'Assoluta',
    analysis_extrema_white: 'Punto di bianco',
    analysis_extrema_black: 'Punto di nero',
    analysis_extrema_blackink: 'Inchiostrazione al punto di nero',
    analysis_extrema_tac: 'TAC',
    analysis_extrema_noabs: 'Questo profilo non ha il tag del punto di bianco del supporto, quindi la colorimetria assoluta non è disponibile.',
    analysis_extrema_err_output: 'La colorimetria degli estremi è disponibile solo per i profili di output (stampante) — presuppone che colorante nullo significhi supporto nudo.',
    analysis_extrema_hue_heading: 'Pieno e croma massima',
    analysis_extrema_hue_intro: 'Dove si colloca ogni vertice d’inchiostro e il punto più cromatico lungo il percorso. Misurato tramite A2B1, quindi queste righe non cambiano con l’intento di rendering sopra. In un profilo ben formato le due righe coincidono; se la croma massima arriva prima del pieno, l’inchiostro oltre quel punto si limita a scurire.',
    analysis_extrema_hue: 'Tinta',
    analysis_extrema_fulltone: 'Pieno',
    analysis_extrema_maxc: 'C* max',
    analysis_extrema_at: 'All’inchiostrazione',
    analysis_extrema_early: 'La croma massima viene raggiunta prima del pieno — oltre questo punto l’inchiostro si limita a scurire.',
    analysis_shadow_heading: 'Uso dell’inchiostro nelle ombre',
    analysis_shadow_intro: 'Quattro percorsi rettilinei sul piano a*b* a una luminosità costante e deliberatamente scura, passati attraverso la tabella B2A selezionata. Tutti i campioni condividono la stessa L*, perciò ogni scalino brusco o inversione di un colorante deriva unicamente dalla gestione di tinta e croma — la firma di un artefatto di mappatura del gamut nelle ombre.',
    analysis_shadow_err_output: 'L’uso dell’inchiostro nelle ombre è disponibile solo per i profili di output (stampante).',
    analysis_shadow_plane: 'Piano a L* costante',
    analysis_shadow_bpc: 'con compensazione del punto di nero da',
    analysis_shadow_xaxis: 'Posizione lungo il percorso',
    analysis_primary_heading: 'Percorsi d’inchiostrazione primaria attraverso il neutro',
    analysis_primary_intro: 'Tre percorsi nel gamut — ciano→rosso, magenta→verde, giallo→blu — ciascuno attraverso l’asse neutro alla chiarezza mediana dei suoi estremi, attraverso la tabella B2A selezionata. Ogni campione è nel gamut, quindi a differenza dei percorsi in ombra qualsiasi salto o inversione di un colorante è un difetto di regolarità della CLUT e non un artefatto di mappatura del gamut.',
    analysis_primary_err_output: 'I percorsi d’inchiostrazione primaria sono disponibili solo per i profili di output (stampante).',
    analysis_primary_xaxis: 'Posizione lungo il percorso (neutro al centro)',
    analysis_primary_bpc: 'Compensazione del punto nero applicata per questo intento.',
    analysis_inkusage_heading: 'Statistiche di utilizzo dell’inchiostro',
    analysis_inkusage_intro: 'Quanto di ogni colorante il profilo deposita, come somma e come quota del totale — la firma di consumo d’inchiostro della separazione.',
