    analysis_extrema_heading: 'Colorimetría de los extremos',
    analysis_extrema_intro: 'Los extremos del rango de reproducción del perfil: el blanco del soporte, el negro más oscuro que imprimirá, la tinta que cuesta ese negro y el punto en el que cada matiz alcanza su máxima saturación.',
    analysis_extrema_method: 'El punto blanco es el color con colorante cero — el soporte desnudo. El punto negro se obtiene pasando el negro del PCS (L*=0, a*=b*=0) por la tabla B2A seleccionada para obtener el entintado que el perfil elige para el negro, y leyendo después ese entintado a través de A2B1. La cobertura total de tinta (TAC) es la suma de ese entintado. La colorimetría absoluta muestra el color propio del soporte; la relativa lo refiere a un blanco perfecto.',
