    analysis_shadow_intro: 'Cuatro trayectos rectos por el plano a*b* con una claridad constante y deliberadamente oscura, pasados por la tabla B2A seleccionada. Todas las muestras comparten la misma L*, así que cualquier salto brusco o inversión de un colorante procede únicamente del tratamiento del matiz y del croma — la firma de un artefacto de mapeo de gama en las sombras.',
