    analysis_rt_desc_rt2: 'iccRoundTrip Ida y vuelta 2: ΔE*ab entre la primera y la segunda ida y vuelta — cómo de estable es una ida y vuelta de PCS repetida (reproducibilidad, independiente del recorte de gama de la primera pasada).',
    analysis_rt_desc_prmg: 'iccRoundTrip PRMG: los colores PCS dentro del Perceptual Reference Medium Gamut realizan una única ida y vuelta (Lab → dispositivo → Lab); la distribución del ΔE*ab indica la interoperabilidad entre perfiles.',
