    analysis_extrema_heading: 'Colorimetria dos extremos',
    analysis_extrema_intro: 'Os extremos da gama de reprodução do perfil: o branco do suporte, o preto mais escuro que irá imprimir, a tinta que esse preto custa e o ponto em que cada matiz atinge a saturação máxima.',
    analysis_extrema_method: 'O ponto branco é a cor com corante nulo — o suporte nu. O ponto preto obtém-se passando o preto do PCS (L*=0, a*=b*=0) pela tabela B2A selecionada para obter a tintagem que o perfil escolhe para o preto e lendo depois essa tintagem através de A2B1. A cobertura total de tinta (TAC) é a soma dessa tintagem. A colorimetria absoluta mostra a cor própria do suporte; a relativa refere-a a um branco perfeito.',
    analysis_extrema_rel: 'Relativa',
