    analysis_extrema_err_output: 'A colorimetria dos extremos só está disponível para perfis de saída (impressora) — pressupõe que corante nulo significa suporte nu.',
    analysis_extrema_hue_heading: 'Tinta plena vs croma máximo',
    analysis_extrema_hue_intro: 'Onde fica cada vértice de tinta e o ponto mais cromático no caminho até lá. Medido através de A2B1, pelo que estas linhas não mudam com a intenção de renderização acima. Num perfil bem comportado as duas linhas coincidem; se o croma máximo surgir antes da tinta plena, a tinta para além desse ponto apenas escurece.',
    analysis_extrema_hue: 'Matiz',
    analysis_extrema_fulltone: 'Tinta plena',
    analysis_extrema_maxc: 'C* máx',
    analysis_extrema_at: 'Com tintagem',
    analysis_extrema_early: 'O croma máximo é atingido antes da tinta plena — a tinta para além deste ponto apenas escurece.',
    analysis_shadow_heading: 'Utilização de tinta nas sombras',
    analysis_shadow_intro: 'Quatro percursos retos no plano a*b* com uma luminosidade constante e deliberadamente escura, passados pela tabela B2A selecionada. Todas as amostras partilham a mesma L*, pelo que qualquer degrau abrupto ou inversão de um corante resulta apenas do tratamento do matiz e do croma — a assinatura de um artefacto de mapeamento de gamut nas sombras.',
    analysis_shadow_err_output: 'A utilização de tinta nas sombras só está disponível para perfis de saída (impressora).',
    analysis_shadow_plane: 'Plano de L* constante',
    analysis_shadow_bpc: 'com compensação do ponto preto a partir de',
