    analysis_primary_heading: 'Trajetos de tintagem primária pelo neutro',
    analysis_primary_intro: 'Três trajetos dentro do gamute — ciano→vermelho, magenta→verde, amarelo→azul — cada um através do eixo neutro na luminosidade média das suas extremidades, através da tabela B2A selecionada. Cada amostra está dentro do gamute, pelo que, ao contrário dos trajetos de sombra, qualquer salto ou inversão de um corante é um defeito de suavidade da CLUT e não um artefacto de mapeamento de gamute.',
