    analysis_neutral_heading: 'Tintagem do eixo neutro',
    analysis_neutral_intro: 'Corante depositado ao longo do eixo neutro (a*=b*=0) conforme a luminosidade vai de branco (L*=100) a preto (L*=0).',
    analysis_neutral_err_output: 'A tintagem do eixo neutro só está disponível para perfis de saída (impressora).',
    analysis_neutral_na: 'Este perfil não tem uma tabela B2A (PCS→dispositivo) para amostrar.',
    analysis_intent_label: 'Intenção de renderização', analysis_neutral_yaxis: '% tinta',
    analysis_neutral_tone: 'L* de saída (tom)',
    analysis_neutral_de: 'Δa*b*',
    analysis_extrema_heading: 'Colorimetria dos extremos',
    analysis_extrema_intro: 'Os extremos da faixa de reprodução do perfil: o branco do suporte, o preto mais escuro que ele imprimirá, a tinta que esse preto custa e o ponto em que cada matiz atinge a saturação máxima.',
    analysis_extrema_method: 'O ponto branco é a cor com corante nulo — o suporte nu. O ponto preto é obtido passando o preto do PCS (L*=0, a*=b*=0) pela tabela B2A selecionada para obter a tintagem que o perfil escolhe para o preto e lendo depois essa tintagem através de A2B1. A cobertura total de tinta (TAC) é a soma dessa tintagem. A colorimetria absoluta mostra a cor própria do suporte; a relativa a refere a um branco perfeito.',
    analysis_extrema_rel: 'Relativa',
    analysis_extrema_abs: 'Absoluta',
    analysis_extrema_white: 'Ponto branco',
    analysis_extrema_black: 'Ponto preto',
    analysis_extrema_blackink: 'Tintagem no ponto preto',
    analysis_extrema_tac: 'TAC',
    analysis_extrema_noabs: 'Este perfil não tem tag de ponto branco do meio, portanto a colorimetria absoluta não está disponível.',
    analysis_extrema_err_output: 'A colorimetria dos extremos só está disponível para perfis de saída (impressora) — ela pressupõe que corante nulo significa suporte nu.',
    analysis_extrema_hue_heading: 'Tinta plena vs croma máximo',
    analysis_extrema_hue_intro: 'Onde fica cada vértice de tinta e o ponto mais cromático no caminho até lá. Medido através de A2B1, portanto estas linhas não mudam com a intenção de renderização acima. Em um perfil bem comportado as duas linhas coincidem; se o croma máximo surgir antes da tinta plena, a tinta além desse ponto apenas escurece.',
    analysis_extrema_hue: 'Matiz',
    analysis_extrema_fulltone: 'Tinta plena',
    analysis_extrema_maxc: 'C* máx',
    analysis_extrema_at: 'Com tintagem',
    analysis_extrema_early: 'O croma máximo é atingido antes da tinta plena — a tinta além deste ponto apenas escurece.',
    analysis_shadow_heading: 'Uso de tinta nas sombras',
    analysis_shadow_intro: 'Quatro percursos retos no plano a*b* com uma luminosidade constante e deliberadamente escura, passados pela tabela B2A selecionada. Todas as amostras compartilham a mesma L*, portanto qualquer degrau abrupto ou inversão de um corante vem apenas do tratamento do matiz e do croma — a assinatura de um artefato de mapeamento de gamut nas sombras.',
    analysis_shadow_err_output: 'O uso de tinta nas sombras só está disponível para perfis de saída (impressora).',
    analysis_shadow_plane: 'Plano de L* constante',
    analysis_shadow_bpc: 'com compensação do ponto preto a partir de',
    analysis_shadow_xaxis: 'Posição ao longo do percurso',
    analysis_primary_heading: 'Caminhos de entintamento primário pelo neutro',
    analysis_primary_intro: 'Três caminhos dentro do gamute — ciano→vermelho, magenta→verde, amarelo→azul — cada um através do eixo neutro na luminosidade média de suas extremidades, através da tabela B2A selecionada. Cada amostra está dentro do gamute, então, diferentemente dos caminhos de sombra, qualquer salto ou inversão de um corante é um defeito de suavidade da CLUT e não um artefato de mapeamento de gamute.',
    analysis_primary_err_output: 'Os caminhos de entintamento primário só estão disponíveis para perfis de saída (impressora).',
    analysis_primary_xaxis: 'Posição ao longo do caminho (neutro no centro)',
