    analysis_neutral_de: 'Δa*b*',
    analysis_extrema_heading: 'Kolorimetri för ytterlägen',
    analysis_extrema_intro: 'Ytterlägena i profilens återgivningsomfång: substratets vithet, det mörkaste svart den trycker, bläcket som det svarta kostar och var varje nyans når sin mest mättade punkt.',
    analysis_extrema_method: 'Vitpunkten är färgen vid noll färgmedel — det bara substratet. Svartpunkten tas fram genom att föra PCS-svart (L*=0, a*=b*=0) genom den valda B2A-tabellen för att få den färgmängd profilen väljer för svart, och sedan läsa tillbaka den färgmängden via A2B1. Den totala färgmängden (TAC) är summan av den färgmängden. Absolut kolorimetri visar substratets egen färg; relativ refererar om den till ett perfekt vitt.',
    analysis_extrema_rel: 'Relativ',
    analysis_extrema_abs: 'Absolut',
    analysis_extrema_white: 'Vitpunkt',
    analysis_extrema_black: 'Svartpunkt',
    analysis_extrema_blackink: 'Färgmängd vid svartpunkten',
    analysis_extrema_tac: 'TAC',
    analysis_extrema_noabs: 'Den här profilen saknar tagg för mediets vitpunkt, så absolut kolorimetri är inte tillgänglig.',
    analysis_extrema_err_output: 'Kolorimetri för ytterlägen är endast tillgänglig för utdataprofiler (skrivare) — den förutsätter att noll färgmedel betyder bart substrat.',
    analysis_extrema_hue_heading: 'Fullton mot maximal kroma',
    analysis_extrema_hue_intro: 'Var varje bläckhörn hamnar, och den mest kromatiska punkten på vägen dit. Mätt via A2B1, så dessa rader ändras inte med renderingsavsikten ovan. I en välartad profil sammanfaller de två raderna; om maximal kroma nås före fullton gör bläcket efter den punkten bara mörkare.',
    analysis_extrema_hue: 'Nyans',
    analysis_extrema_fulltone: 'Fullton',
    analysis_extrema_maxc: 'Max C*',
    analysis_extrema_at: 'Vid färgmängd',
    analysis_extrema_early: 'Maximal kroma nås före fullton — bläck efter denna punkt gör bara mörkare.',
    analysis_shadow_heading: 'Bläckförbrukning i skuggor',
    analysis_shadow_intro: 'Fyra raka banor genom a*b*-planet vid en konstant, medvetet mörk ljushet, förda genom den valda B2A-tabellen. Alla sampel har samma L*, så varje abrupt steg eller omkastning i ett färgmedel kommer enbart från hanteringen av nyans och kroma — signaturen för en gamutmappningsartefakt i skuggorna.',
    analysis_shadow_err_output: 'Bläckförbrukning i skuggor är endast tillgänglig för utdataprofiler (skrivare).',
    analysis_shadow_plane: 'Plan med konstant L*',
    analysis_shadow_bpc: 'svartpunktskompenserad från',
    analysis_shadow_xaxis: 'Position längs banan',
    analysis_primary_heading: 'Primärbläckvägar genom neutralt',
    analysis_primary_intro: 'Tre vägar inom färgomfånget — cyan→röd, magenta→grön, gul→blå — var och en genom neutralaxeln vid mittljusheten för sina ändpunkter, genom den valda B2A-tabellen. Varje sampel ligger inom omfånget, så till skillnad från skuggvägarna är varje plötsligt steg eller omkastning i ett färgämne ett CLUT-jämnhetsfel snarare än en omfångsmappningsartefakt.',
    analysis_primary_err_output: 'Primärbläckvägar är endast tillgängliga för utdataprofiler (skrivare).',
    analysis_primary_xaxis: 'Position längs vägen (neutralt i mitten)',
