    analysis_extrema_intro: '配置文件复现范围的两端：承印物白、它能打印的最深黑、该黑所耗的墨量，以及每个色相达到最饱和的位置。',
    analysis_extrema_method: '白点是零色料时的颜色——即空白承印物。黑点的求法是把 PCS 黑（L*=0，a*=b*=0）送入所选 B2A 表，得到配置文件为黑色选择的墨量，再把该墨量经 A2B1 读回。总墨量（TAC）即该墨量之和。绝对比色显示承印物自身的颜色；相对比色则将其重新参照到理想白。',
