    analysis_shadow_heading: '暗调中的用墨',
    analysis_shadow_intro: '在一个恒定且刻意偏暗的明度上，沿 a*b* 平面取四条直线路径，送入所选 B2A 表。所有采样点的 L* 相同，因此某个色料出现的任何突变或反转都只能来自色相与彩度的处理——这正是暗调色域映射伪影的特征。',
