    analysis_primary_heading: '经中性轴的原色墨路',
    analysis_primary_intro: '色域内的三条路径——青→红、品红→绿、黄→蓝——每条都在其两端明度的中点经过中性轴，通过所选的 B2A 表。每个采样点都在色域内，因此与暗调路径不同，某个着色剂的任何突变或反转都是 CLUT 平滑性缺陷，而非色域映射伪影。',
