    analysis_extrema_heading: '극값 측색',
    analysis_extrema_intro: '프로파일 재현 범위의 양 끝: 기재의 백색, 인쇄할 수 있는 가장 어두운 검정, 그 검정에 드는 잉크량, 그리고 각 색상이 가장 진해지는 지점.',
    analysis_extrema_method: '백색점은 색료가 0일 때의 색 — 즉 아무것도 인쇄하지 않은 기재입니다. 흑색점은 PCS 검정(L*=0, a*=b*=0)을 선택한 B2A 테이블에 통과시켜 프로파일이 검정에 대해 선택하는 잉킹을 얻은 뒤, 그 잉킹을 A2B1로 되읽어 구합니다. 총 잉크량(TAC)은 그 잉킹의 합입니다. 절대 측색은 기재 자체의 색을 보여 주고, 상대 측색은 이를 완전한 백색 기준으로 다시 맞춥니다.',
    analysis_extrema_rel: '상대',
    analysis_extrema_abs: '절대',
    analysis_extrema_white: '백색점',
    analysis_extrema_black: '흑색점',
    analysis_extrema_blackink: '흑색점에서의 잉킹',
    analysis_extrema_tac: 'TAC',
    analysis_extrema_noabs: '이 프로파일에는 매체 백색점 태그가 없으므로 절대 측색을 사용할 수 없습니다.',
    analysis_extrema_err_output: '극값 측색은 출력(프린터) 프로파일에서만 사용할 수 있습니다 — 색료가 0이면 아무것도 인쇄하지 않은 기재라고 가정합니다.',
    analysis_extrema_hue_heading: '솔리드 대 최대 크로마',
    analysis_extrema_hue_intro: '각 잉크 꼭짓점의 위치와 거기에 이르는 도중 크로마가 가장 높은 지점입니다. A2B1을 통해 측정하므로 이 행들은 위의 렌더링 의도에 따라 바뀌지 않습니다. 정상적인 프로파일에서는 두 행이 일치합니다. 최대 크로마가 솔리드보다 먼저 도달하면 그 지점을 넘어선 잉크는 어둡게만 만듭니다.',
    analysis_extrema_hue: '색상',
    analysis_extrema_fulltone: '솔리드',
    analysis_extrema_maxc: '최대 C*',
    analysis_extrema_at: '해당 잉킹',
    analysis_extrema_early: '최대 크로마가 솔리드보다 먼저 도달합니다 — 이 지점을 넘어선 잉크는 어둡게만 만듭니다.',
    analysis_shadow_heading: '섀도 영역의 잉크 사용량',
    analysis_shadow_intro: '의도적으로 어둡게 고정한 하나의 명도에서 a*b* 평면을 가로지르는 네 개의 직선 경로를 선택한 B2A 테이블에 통과시킵니다. 모든 샘플이 같은 L*를 공유하므로 어떤 색료에 나타나는 급격한 단차나 반전은 오직 색상과 크로마 처리에서 비롯됩니다 — 섀도 영역 색역 매핑 아티팩트의 특징입니다.',
    analysis_shadow_err_output: '섀도 영역의 잉크 사용량은 출력(프린터) 프로파일에서만 사용할 수 있습니다.',
    analysis_shadow_plane: 'L* 고정 평면',
    analysis_shadow_bpc: '흑색점 보정 기준',
    analysis_shadow_xaxis: '경로상 위치',
    analysis_primary_heading: '중성축을 지나는 원색 잉킹 경로',
    analysis_primary_intro: '색역 내의 세 경로 — 사이언→레드, 마젠타→그린, 옐로→블루 — 각각 양 끝점 명도의 중간에서 중성축을 지나 선택한 B2A 테이블을 통과합니다. 모든 샘플이 색역 안에 있으므로, 섀도 경로와 달리 착색제의 급격한 단차나 반전은 색역 매핑 아티팩트가 아니라 CLUT 평활도 결함입니다.',
    analysis_primary_err_output: '원색 잉킹 경로는 출력(프린터) 프로파일에서만 사용할 수 있습니다.',
